/**
 * بيانات مرجعية حقيقية لمكينات البوابات المنزلقة، مستخرجة من أدلة الشركات المنشورة.
 * ليست بيانات «تجريبية» (isSeed=false) فلا تُحذف مع حذف البيانات التجريبية.
 * كل عنصر يحمل رابط مصدره. ما لم يرد في الدليل المتاح كُتب صراحةً «غير مذكور» ولم يُختلق.
 * مهم: القيم مأخوذة من نسخ منشورة وقد تختلف حسب إصدار اللوحة أو الدفعة؛ تحقق من دليل المكينة التي أمامك.
 */
object ReferenceData {
    const val CATEGORY = "البوابات المنزلقة"
    const val CATEGORY_GARAGE = "مكينات أبواب الجراج العلوية"
    const val CATEGORY_SWING = "البوابات ذات الضلفتين (المفصلية)"

    private const val SRC_SOMFY_DEXXO = "كتالوج Somfy DEXXO PRO 800-1000 RTS (مقتطف فني): https://pdf.archiexpo.com/ja/pdf-en/somfy/dexxo-pro-800-1000-rts/3190-407029.html"
    private const val SRC_MARANTEC_COMFORT = "دليل تشغيل Marantec Comfort 260/270/280 الكامل (#100316 – GB، إصدار 04.2016، 30 صفحة) — من الملف الذي رفعه المستخدم."
    private const val SRC_MARANTEC_COMFORT360 = "دليل تشغيل Marantec Comfort 360/370/380 الكامل (#101258 – GB، إصدار 04.2016، 32 صفحة) — من الملف الذي رفعه المستخدم."

