    private const val SRC_ETNICE_DRIVE500 = "دليل تركيب ET NICE DRIVE 500 / DRIVE 600 (لمحركات بوابات منزلقة حتى 500 كغ)، الشركة المصنّعة ET NICE (Pty) Ltd — جنوب أفريقيا (اسم تجاري منفصل تمامًا عن شركة Nice الإيطالية، رغم التشابه اللفظي): https://ismartgate.com/manuals/Nice_ET_500_manual.pdf — تم استخراج المحتوى عبر أداة WebFetch (قراءة مباشرة لرابط PDF) وليس من ملف مرفوع محليًا؛ مخطط التوصيل الفعلي (صفحة 15) كان صورة لم تُستخرج نصيًا، فلا تتوفر أرقام أطراف توصيل فعلية لهذا الموديل — فقط أسماء الدارات الخارجية المذكورة نصيًا في الدليل."
    private const val SRC_CENTURION_D5EVO = "دليل تركيب Centurion Systems D5-Evo / D5-Evo Low-Voltage (جنوب أفريقيا، لمحركات بوابات منزلقة): https://ismartgate.com/manuals/Centsys_D5_EVO_manual.pdf — تم استخراج المحتوى عبر أداة WebFetch (قراءة مباشرة لرابط PDF) وليس من ملف مرفوع محليًا. الدليل نفسه يحتوي عدة تعارضات داخلية في بعض القيم (مذكورة أدناه صراحة حيثما وردت) بين جدول المواصفات وأقسام أخرى من نفس الدليل."
    private const val SRC_LIFTMASTER_SL3000 = "دليل مالك LiftMaster SL3000UL8 / SL3000ULDM8 / SL3000UL1HP8 (مكينات بوابات منزلقة مركبات، السوق الأمريكي، متوافقة مع UL325): https://ismartgate.com/manuals/LiftMaster_SL3000UL8_manual.pdf — تم استخراج المحتوى عبر أداة WebFetch وليس من ملف مرفوع محليًا. الدليل نفسه يحتوي تعارضًا صريحًا في تصنيف نوع البوابة (غلاف الدليل يذكر «بوابة مفصلية Swing» بينما قسم النظرة العامة يذكر «بوابة منزلقة Slide» لنفس الموديل)، وتعارضات أخرى في تسمية بعض الأعطال ومخططات الأطراف — كلها مُشارة أدناه صراحة."
    private const val SRC_NICE_ROBUS = "الدليل الرسمي الفرنسي لـ Nice ROBUS RBS400 / RBS600 / RBS600HS (مكينات بوابات منزلقة، من موقع الشركة الرسمي niceforyou.com): https://www.niceforyou.com/sites/default/files/upload/manuals/IDV0777A00FR.pdf — تم استخراج المحتوى عبر أداة WebFetch من نسخة فرنسية (ترجمة النص الأصلي الإيطالي) وليس من ملف مرفوع محليًا؛ بعض الأقسام (منها معظم جدول استكشاف الأعطال، الفقرة الثانية من معاملات البرمجة، وإجراء مسح الذاكرة) كانت مقتطعة أو غير متاحة بالكامل في النسخة المستخرَجة — مُشار إليها أدناه صراحة كـ«غير مذكور»."

    private const val SRC_ROGER = "دليل Roger BM30/HS: https://ismartgate.com/manuals/Roger_BM30_manual.pdf"
    private const val SRC_ROGER_ACC = "دليل التوصيلات السريع (Quick Reference) لمحركات Roger BM30/HS وBH30/HS وBH30/80 بلوحة B70/1DC — من الملف الذي رفعه المستخدم (Accessory Connections)."
    private const val SRC_BENINCA_BULL = "دليل تركيب وبرمجة Beninca BULL 424 ESA / 624 ESA (L8543223، إصدار 09/2016) — لوحة CP.B24 ESA / CP.B1024 ESA؛ من الملف الذي رفعه المستخدم."
    private const val SRC_BENINCA_CPBULL8OM = "دليل لوحة Beninca CP.BULL8 OM (L8542646، إصدار 03/2013) — لوحة تحكم لمحرك واحد 230Vac لبوابات منزلقة؛ من الملف الذي رفعه المستخدم."
    private const val SRC_CAME_FROG = "دليل تركيب CAME FROG KIT (تحت-أرضي لبوابتين مفصليتين، لوحة تحكم ZA4) — نسخة CAME United Kingdom Ltd، من الملف الذي رفعه المستخدم."
    private const val SRC_MOTORLINE = "دليل لوحة Motorline MC50SC (v7.3): https://ismartgate.com/manuals/Motorline_MC50SC_manual.pdf"
    private const val SRC_DEA = "دليل DEA LIVI: https://manualslib.mx/manual/369786/Dea-Livi.html?page=10 — ولوحة NET24N: https://manualslib.mx/manual/133241/Dea-Net24N.html?page=45"
    private const val SRC_BFT = "كتالوج BFT ARES/DEIMOS ULTRA BT A: https://pdf.archiexpo.com/pdf/bft/ares-ultra-bt/46-267146.html"
    private const val SRC_BFT_DEIMOS_UL = "دليل BFT DEIMOS BT KIT UL — Quick Reference Guide (الإصدار الأمريكي 120V، لوحة QSCD UL، 20 صفحة) — من الملف الذي رفعه المستخدم."
    private const val SRC_CAME_V6000 = "دليل تركيب وتشغيل CAME V6000 الكامل (FA00047-EN، إصدار 1، 06/2015، 20 صفحة) — من الملف الذي رفعه المستخدم."

    private const val W_GEN =
        "افصل التيار الرئيسي (وافصل البطاريات الاحتياطية) قبل أي عمل على اللوحة. لا تعطّل كشف العوائق ولا الفوتوسيل. " +
            "لا تترك المكينة في وضع الفك اليدوي بعد الانتهاء. هذه الخطوات منقولة من دليل الشركة وللفنيين المؤهلين فقط."

    suspend fun populate(repo: AppRepository) {
        val existing = repo.categoriesOnce().firstOrNull { it.name == CATEGORY }
        // التصنيف يصبح ملكًا للمستخدم (غير تجريبي) كي لا يمنع حذف البيانات التجريبية.
        if (existing != null && existing.isSeed) repo.saveCategory(existing.copy(isSeed = false))
        val catId = existing?.id
            ?: (repo.saveCategory(DoorCategory(name = CATEGORY, description = "بوابات سيارات تنزلق أفقيًا.")) as? Outcome.Ok)?.id

        // قسم ثانٍ مستقل: مكينات أبواب الجراج العلوية (Overhead Garage Door Openers) — لا يُخلط بموديلات البوابات المنزلقة أعلاه.
        val existingGarage = repo.categoriesOnce().firstOrNull { it.name == CATEGORY_GARAGE }
        if (existingGarage != null && existingGarage.isSeed) repo.saveCategory(existingGarage.copy(isSeed = false))
        val catIdGarage = existingGarage?.id
            ?: (repo.saveCategory(DoorCategory(name = CATEGORY_GARAGE, description = "مكينات أبواب الجراج التي تُفتح لأعلى (سكشنال أو قطعة واحدة).")) as? Outcome.Ok)?.id

        // قسم ثالث مستقل: البوابات ذات الضلفتين (المفصلية) — مكينات الذراع أو التحت-أرضية لبوابتين متقابلتين تفتحان للداخل أو الخارج.
        val existingSwing = repo.categoriesOnce().firstOrNull { it.name == CATEGORY_SWING }
        if (existingSwing != null && existingSwing.isSeed) repo.saveCategory(existingSwing.copy(isSeed = false))
        val catIdSwing = existingSwing?.id
            ?: (repo.saveCategory(DoorCategory(name = CATEGORY_SWING, description = "بوابات مفصلية بضلفتين (أو ضلفة واحدة) تفتحان بالدوران حول مفصلة، بمكينات ذراع أو تحت-أرضية.")) as? Outcome.Ok)?.id

        suspend fun brand(name: String, country: String): Long =
            repo.brandsOnce().firstOrNull { it.name == name }?.id
                ?: ((repo.saveBrand(Brand(name = name, country = country)) as? Outcome.Ok)?.id ?: 0L)

        suspend fun model(m: MachineModel): Long? {
            repo.modelsOnce().firstOrNull { it.brandId == m.brandId && it.name == m.name }?.let { return it.id }
            return (repo.saveModel(m) as? Outcome.Ok)?.id
        }

        /**
         * يزرع صورة حقيقية (صورة المكينة أو صفحة مخطط توصيل ممسوحة من الكتالوج الأصلي)
         * مرفقة داخل app/src/main/assets/diagrams كمرفق MediaAttachment لموديل أو دليل.
         * آمن للتكرار: لو المرفق بنفس اسم الملف موجود بالفعل لنفس المالك، ميضيفوش تاني.
         */
        suspend fun img(ownerType: String, ownerId: Long?, assetFile: String) {
            if (ownerId == null || ownerId == 0L) return
            val fileName = "seed_$assetFile"
            if (repo.mediaOnce(ownerType, ownerId).any { it.path == fileName }) return
            if (repo.mediaStore.copyFromAssets("diagrams/$assetFile", fileName) == null) return
            repo.addCameraImage(ownerType, ownerId, repo.mediaStore.fileFor(fileName))
        }

        val came = brand("CAME", "إيطاليا")
        val faac = brand("FAAC", "إيطاليا")
        val nice = brand("Nice", "إيطاليا")

        // ======================= CAME BX =======================
        val bx74 = model(MachineModel(
            brandId = came, categoryId = catId, name = "BX-74", controlUnit = "لوحة ZB74-78",
            specs = "230V AC 50/60Hz • 200W • أقصى وزن للبوابة 400 كغ • وزن المكينة 15 كغ",
            remoteInfo = "حفظ مباشر على اللوحة بزر CH1/CH2 (انظر دليل الريموت).",
            sensorsInfo = "مداخل أمان NC (فوتوسيل/حافة). فتح تلامس أمان NC يُظهر وميض LED الإشارة.",
            notes = "الدليل للمركّبين المحترفين فقط.", source = SRC_CAME,
        ))
        val bx78 = model(MachineModel(
            brandId = came, categoryId = catId, name = "BX-78", controlUnit = "لوحة ZB74-78",
            specs = "230V AC 50/60Hz • 300W • أقصى وزن للبوابة 800 كغ (600 كغ في الاستخدام السكني المشترك) • وزن المكينة 15 كغ",
            remoteInfo = "حفظ مباشر على اللوحة بزر CH1/CH2 (انظر دليل الريموت).",
            sensorsInfo = "مداخل أمان NC (فوتوسيل/حافة).",
            notes = "الدليل للمركّبين المحترفين فقط.", source = SRC_CAME,
        ))

        // ======================= CAME V6000 (مكينة جراج علوية) =======================
        val v6000 = model(MachineModel(
            brandId = came, categoryId = catIdGarage, name = "V6000", controlUnit = "لوحة تحكم مدمجة داخل غطاء المشغّل، بشاشة عرض رقمية (digit واحد) وأزرار P / + / - وزر حفظ ريموت S",
            specs = "مساحة الباب القصوى 9م² • أقصى ارتفاع لباب علوي متوازن بثقل مضاد (Counterbalanced) 2.4م • أقصى ارتفاع لباب علوي بزنبرك (Spring-balanced) 3.25م • أقصى ارتفاع لباب سكشنال 3.20م. " +
                "درجة حماية IP40 • تغذية 230V AC 50/60Hz • تغذية المحرك 24V DC • استهلاك الاستعداد 7W • أقصى قدرة للملحقات 35W • القدرة الاسمية 100W • سرعة الفتح 6م/دقيقة • قوة الجر 600N • مدى حرارة التشغيل -20 إلى +55°م • فئة عزل II (مزدوج العزل) • الوزن 4.9 كغ.",
            remoteInfo = "حفظ حتى 16 كود/جهاز ريموت عبر زر S على اللوحة (اضغط مطولًا حتى يظهر 0 يومض، ثم اضغط مفتاح الريموت مرتين متتاليتين). يمكن حذف كل الرموت دفعة واحدة بنفس الزر S (اضغط مطولًا حتى يظهر 00 ثم أفلت الزر فور اختفاء الصفر الأيسر).",
            sensorsInfo = "طرف أمان (NC) لإعادة الفتح أثناء الإغلاق: يقبل فوتوسيل وحافة أمان حساسة متوافقة مع EN 12978 — فتح هذا التلامس أثناء الإغلاق يعكس الحركة حتى الفتح الكامل. طرف أوامر (NO) للتشغيل Open-Stop-Close-Stop من مفتاح مفتاحي أو جهاز تحكم. طرف STOP (NC) يوقف الحركة ويلغي الإغلاق التلقائي. أي طرف أمان غير مستخدم يجب إبقاء الجسر (Bridge) الأصلي عليه؛ إزالة الجسر فقط عند توصيل جهاز فعلي.",
            notes = "البيانات من الدليل الرسمي الكامل (20 صفحة: التركيب، التوصيلات، البرمجة الكاملة، الريموت، الصيانة، جدول الأعطال). المشغّل مزوّد بسلك تغذية 1.2م بقابس Shuko جاهز.",
            source = SRC_CAME_V6000,
        ))

        // ======================= FAAC 844 ER =======================
        val faac844 = model(MachineModel(
            brandId = faac, categoryId = catId, name = "844 ER (Z16 / Z20)", controlUnit = "لوحة 780D مدمجة بشاشة وأزرار",
            specs = "Z16: وزن حتى 1800 كغ • طول حتى 40 م • 9.5 م/د • دفع أقصى 1160N | " +
                "Z20: وزن حتى 1000 كغ • طول حتى 50 م • 12 م/د • دفع أقصى 930N | " +
                "230V (أو 115V) • مكثف 12.5µF • حماية حرارية 120°C • IP44 • الزيت FAAC HP OIL • وزن 14.5 كغ • فيوزات F1 5A(230V)/10A(115V) وF2 T0.8A",
            remoteInfo = "كارت راديو على موصل J2 (5 أطراف، اتجاه تركيب واحد). خطوات الحفظ في تعليمات الكارت وليست في الدليل المتاح.",
            sensorsInfo = "مداخل: OPEN A / OPEN B / FSW OP / FSW CL / STOP / SAFE / TX-FSW. مفاتيح حد حثية J8 أو مغناطيسية J9. تحميل ملحقات 24V حتى 500mA.",
            notes = "المشفّر (Encoder) يكشف العوائق (EC). مفاتيح الحد على الكريمايير.", source = SRC_FAAC,
        ))

        // ======================= Nice RUN =======================
        val run1800 = model(MachineModel(
            brandId = nice, categoryId = catId, name = "RUN1800 / RUN1800P", controlUnit = "لوحة مدمجة (الدليل المتاح لا يذكر رقم اللوحة؛ راجع ملصق المكينة)",
            specs = "وزن حتى 1800 كغ • عزم ذروة 40Nm (1110N) • اسمي 20Nm (560N) • قدرة قصوى 700W • سرعة بلا حمل 10 م/د (12 م/د لإصدار V1) • حتى 11 دورة/ساعة لمصراع 15 م • طول حتى 15 م • مفتاح الحد: ميكانيكي (RUN1800) أو حثي (RUN1800P)",
            remoteInfo = "مستقبل SMXI/SMXIS (أو OXI) على موصل SM، 433.92MHz. مخارج: 1 خطوة-بخطوة • 2 فتح جزئي • 3 فتح • 4 إغلاق.",
            sensorsInfo = "BlueBUS للملحقات (تعلّم الأجهزة بضغط ▲+Set).",
            notes = "صيانة كل 6 أشهر أو 20,000 مناورة. قوة الفك اليدوي القصوى 390N.", source = SRC_NICE,
        ))
        val run2500 = model(MachineModel(
            brandId = nice, categoryId = catId, name = "RUN2500 / RUN2500P", controlUnit = "لوحة مدمجة (الدليل المتاح لا يذكر رقم اللوحة؛ راجع ملصق المكينة)",
            specs = "وزن حتى 2500 كغ • عزم ذروة 50Nm (1390N) • اسمي 30Nm (830N) • قدرة قصوى 870W • سرعة بلا حمل 10 م/د • حتى 15 دورة/ساعة لمصراع 15 م • طول حتى 18 م • مفتاح الحد: ميكانيكي (RUN2500) أو حثي (RUN2500P)",
            remoteInfo = "مثل RUN1800: SMXI/SMXIS/OXI على موصل SM.",
            sensorsInfo = "BlueBUS للملحقات.",
            notes = "صيانة كل 6 أشهر أو 20,000 مناورة.", source = SRC_NICE,
        ))

        // ======================= Nice 1050 (لوحة تحكم) + مشغّل خطي 816 — طقم 1551 (سوق أمريكي UL325) =======================
        val nice1050 = model(MachineModel(
            brandId = nice, categoryId = catIdSwing, name = "لوحة 1050 + مشغّل خطي 816 (طقم 1551)", controlUnit = "لوحة تحكم 1050 (منفصلة عن المشغّل، تُركَّب في صندوق خاص) — منظومة Nice BlueBUS",
            specs = "تغذية التحكم 12V DC. جدول المواصفات في الدليل يذكر مدخل تغذية DC رئيسي 10-32V DC بينما قسم توصيل التغذية يذكر 10-35V DC — تعارض داخلي في الدليل نفسه لم يُحسم، فيُكتفى بذكر كلا الرقمين دون ترجيح. " +
                "يدعم نوعي بوابة من قائمة البرمجة (Learn menu، القسم 31.5): مفصلية (Swing) أو منزلقة (Slide) — يُختار النوع أثناء البرمجة، فالمنظومة ليست حصرية لنوع واحد رغم أن المشغّل 816 خطي (Linear Actuator) يُستخدم غالبًا على البوابات المفصلية. " +
                "منفذ لوحة شمسية (Solar Panel) ومنفذ بطارية احتياطية (Battery) منفصلان عن مدخل التغذية الرئيسي.",
            remoteInfo = "مستقبل راديو OXI/A يُركَّب على اللوحة (نفس عائلة مستقبلات BlueBUS/OXI المستخدمة في منتجات Nice الأخرى). برمجة الريموت: إضافة/نسخ جهاز جديد، حذف جهاز واحد، أو حذف كل الذاكرة — الخطوات التفصيلية في القسم 20.4 من الدليل.",
            sensorsInfo = "منظومة BlueBUS لتوصيل الملحقات (فوتوسيلات وحساسات) بدل التوصيل التقليدي بأطراف منفصلة لكل جهاز. مداخل أمان/حافة محددة باسمها على اللوحة: SAFETY وSHADOW وENTRAP وEDGE، بالإضافة إلى EXIT وFIRE كمداخل أوامر خاصة؛ الدليل لا يذكر صراحة طرف أرضي (Ground) مخصصًا لهذه المداخل تحديدًا. مخارج OUT1/OUT2 (ريلايات قابلة للبرمجة)، طرف قفل كهربائي (Magnetic Lock)، مدخل/مخرج لمحطة حراسة (Guard Station: OPEN/STOP/CLOSE) وأوامر راديو منفصلة (Radio OPEN/CLOSE). يوجد جسر/مفتاح FAIL SAFE وطرف تأريض (Earth Ground) عام للوحة.",
            notes = "⚠️ هذا الموديل مصدره مختلف عن بقية موديلات هذا التطبيق: تم استخراج بياناته عبر أداة WebFetch من رابط PDF مباشر (وليس من ملف مرفوع محليًا تمت قراءته صفحة بصفحة)، لذلك لا تتوفر له صور كتالوج حقيقية أو أيقونة منتج مقصوصة كبقية الموديلات. بعض القيم أعلاه مُشار إليها صراحة كمتعارضة أو غير مؤكدة في الدليل نفسه؛ يُنصح بتأكيدها من دليل المكينة الفعلي أو ملصقها قبل الاعتماد عليها في التركيب.",
            source = SRC_NICE_1050,
