            sensorsInfo = "لوحة B70/1DC — أطراف الأوامر والأمان: COM/FT2/FT1/COS2/COS1/COM/ST (فوتوسيل 1 وFT2، حافتا أمان COS1/COS2، STOP) و+LAM/COM (فلاشر 24Vdc) و+24V/PED/PP/CH/AP/ORO/COM (تغذية ملحقات، فتح جزئي، خطوة-بخطوة، إغلاق، فتح، تايمر). مخرجا حد الشوط FCA/FCC Open Collector مع COM. أكواد حالة الشاشة: 00 لا عطل، Sb مقبض الفك مفتوح، 15 STOP مفتوح، 13/12 حافة أمان COS1/COS2 مفتوحة، 11/10 فوتوسيل FT1/FT2 مفتوح، FE خطأ بكلا حدّي الشوط، FA/FC حد الفتح/الإغلاق تم الوصول إليه.",
            notes = "قوى الاصطدام تُقاس وفق EN 12445 وتُضبط السرعة والعزم من اللوحة. مصدر تفاصيل الأطراف والأكواد: $SRC_ROGER_ACC", source = SRC_ROGER,
        ))

        // ======================= Centurion D5-Evo / D5-Evo Low-Voltage =======================
